use semio_s_artifact_norm_contract::sqlite_native as n;
use semio_s_artifact_norm_contract::sqlite_native::Column::*;
fn count(root:&R)->Result<usize,ValueError>{let walls=n::list(n::field(root,4)?)?;let mut rows=n::add(n::add(1,walls.len())?,n::list(n::field(root,5)?)?.len())?;rows=n::add(rows,n::list(n::field(root,7)?)?.len())?;rows=n::add(rows,n::list(n::field(root,8)?)?.len())?;for wall in walls{let wall=n::record(wall)?;rows=n::add(rows,n::list(n::field(wall,8)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,33)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,34)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,35)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,36)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,37)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,38)?)?.len())?;rows=n::add(rows,n::list(n::field(wall,39)?)?.len())?;let cases=n::list(n::field(wall,32)?)?;rows=n::add(rows,cases.len())?;for case in cases{rows=n::add(rows,n::list(n::field(n::record(case)?,11)?)?.len())?}}let design=n::list(n::field(root,6)?)?;rows=n::add(rows,design.len())?;for case in design{let case=n::record(case)?;rows=n::add(rows,n::list(n::field(case,4)?)?.len())?;rows=n::add(rows,n::list(n::field(case,5)?)?.len())?}Ok(rows)}
fn write(root:&R,out:&mut RowWriter<'_,'_>)->Result<(),ValueError>{
 out.insert_key("en1996_document",1,&n::cells(root,[Enumeration(0,&["En","De"]),Enumeration(1,&["Class1","Class2","Class3","Class4","Class5"]),Enumeration(2,&["Persistent","Transient","Accidental","Seismic"]),Unsigned(3,u32::MAX as u64),Enumeration(9,&["RC1","RC2","RC3"])])?)?;
 for(index,wall)in n::list(n::field(root,4)?)?.iter().enumerate(){let wall=n::record(wall)?;let parent=n::entity(out,"en1996_wall",1,index,&n::cells(wall,[Text(0),Text(1),Text(2),Enumeration(3,&["LoadBearing","Shear","NonLoadBearing",Real(4)]),Real(4),Real(5),Real(6),Unsigned(7,u8::MAX as u64),Real(9),Real(10),Real(11),Enumeration(12,&["Group1","Group2","Group3","Group4"]),Enumeration(13,&["Clay","CalciumSilicate","Aerated","Concrete"]),Real(14),Real(15),Real(16),Real(17),Enumeration(18,&["GeneralPurpose","ThinLayer","Lightweight"]),Enumeration(19,&["M1","M2_5","M5","M10","M15","M20"]),Real(20),Real(21),Boolean(22),Real(23),Real(24),Real(25),Unsigned(26,u32::MAX as u64),Enumeration(27,&["Mx1","Mx2","Mx3","Mx4","Mx5"]),Real(28),Real(29),Real(30),Boolean(31),Enumeration(40,&["Exempt","Moderate","Severe"]),Real(41),Real(42),Real(43),Real(44),Real(45),Real(46),Real(47),Real(48),Real(49),Real(50),Enumeration(51,&["Unreinforced","Confined","Reinforced"]),Real(52)])?,WALL_FLOATS)?;
 for(index,opening)in n::list(n::field(wall,8)?)?.iter().enumerate(){n::entity(out,"en1996_opening",parent,index,&n::cells(n::record(opening)?,[Text(0),Real(1),Real(2),Real(3),Real(4)])?,OPENING_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,33)?)?.iter().enumerate(){n::entity(out,"en1996_pier",parent,index,&n::cells(n::record(row)?,[Text(0),Real(1),Real(2)])?,PIER_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,34)?)?.iter().enumerate(){n::entity(out,"en1996_lintel",parent,index,&n::cells(n::record(row)?,[Text(0),Real(1),Real(2),Real(3),Real(4)])?,LINTEL_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,35)?)?.iter().enumerate(){n::entity(out,"en1996_tie",parent,index,&n::cells(n::record(row)?,[Text(0),Enumeration(1,&["WallTie","Anchor","RingTie"]),Real(2),Real(3),Real(4)])?,TIE_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,36)?)?.iter().enumerate(){n::entity(out,"en1996_prestress",parent,index,&n::cells(n::record(row)?,[Text(0),Real(1),Real(2),Real(3),Real(4),Real(5),Real(6)])?,PRESTRESS_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,37)?)?.iter().enumerate(){n::entity(out,"en1996_confined",parent,index,&n::cells(n::record(row)?,[Text(0),Real(1),Real(2),Real(3),Real(4)])?,CONFINED_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,38)?)?.iter().enumerate(){n::entity(out,"en1996_flange",parent,index,&n::cells(n::record(row)?,[Text(0),Real(1),Real(2),Real(3)])?,FLANGE_FLOATS)?;}
 for(index,row)in n::list(n::field(wall,39)?)?.iter().enumerate(){n::entity(out,"en1996_bar",parent,index,&n::cells(n::record(row)?,[Text(0),Enumeration(1,&["Anchorage","Shear","DeepBeam"]),Real(2),Real(3),Real(4)])?,BAR_FLOATS)?;}
 for(index,case)in n::list(n::field(wall,32)?)?.iter().enumerate(){let case=n::record(case)?;let parent=n::entity(out,"en1996_load_case",parent,index,&n::cells(case,[Text(0),Text(1),Text(2),Real(3),Real(4),Real(5),Real(6),Real(7),Real(8),Real(9),Real(10)])?,LOAD_CASE_FLOATS)?;
 for(index,load)in n::list(n::field(case,11)?)?.iter().enumerate(){n::entity(out,"en1996_concentrated_load",parent,index,&n::cells(n::record(load)?,[Text(0),Real(1),Real(2),Real(3),Real(4),Real(5)])?,CONCENTRATED_FLOATS)?;}}}
 for(index,p)in n::list(n::field(root,5)?)?.iter().enumerate(){n::entity(out,"en1996_placement",1,index,&n::cells(n::record(p)?,[Text(0),Real(1),Real(2),Real(3),Real(4)])?,PLACEMENT_FLOATS)?;}
 for(index,row)in n::list(n::field(root,7)?)?.iter().enumerate(){n::entity(out,"en1996_chase",1,index,&n::cells(n::record(row)?,[Text(0),Text(1),Enumeration(2,&["Vertical","Horizontal","Recess"]),Real(3),Real(4),Real(5),Real(6),Real(7)])?,CHASE_FLOATS)?;}
 for(index,row)in n::list(n::field(root,8)?)?.iter().enumerate(){n::entity(out,"en1996_movement_joint",1,index,&n::cells(n::record(row)?,[Text(0),Text(1),Real(2)])?,MOVEMENT_JOINT_FLOATS)?;}
 for(index,c)in n::list(n::field(root,6)?)?.iter().enumerate(){let c=n::record(c)?;let parent=n::entity(out,"en1996_case",1,index,&n::cells(c,[Text(0),Text(1),Text(2),Text(3)])?,&[])?;
 for(i,r)in n::list(n::field(c,4)?)?.iter().enumerate(){n::entity(out,"en1996_case_number",parent,i,&n::cells(n::record(r)?,[Text(0),Real(1)])?,CASE_NUMBER_FLOATS)?;}
 for(i,r)in n::list(n::field(c,5)?)?.iter().enumerate(){n::entity(out,"en1996_case_text",parent,i,&n::cells(n::record(r)?,[Text(0),Text(1)])?,&[])?;}}
 Ok(())
}
/// 🛂️ Eighteen authored SQL tables and complete copied semantic controls.
pub fn admit(root:&R,native:&mut NativeDecodeControl<'_>,limits:store::sqlite_snapshot::SqliteDatabaseLimits)->Result<(),ValueError>{n::admit(root,native,limits,En1996Snapshot::SQLITE_SCHEMA,18,105,count(root)?,write)}
